# ==========================================
# PDF REPORT GENERATOR
# ==========================================

def create_pdf_report(title, analysis_text, df):

    buffer = BytesIO()

    doc = SimpleDocTemplate(
        buffer,
        pagesize=A4,
        rightMargin=40,
        leftMargin=40,
        topMargin=40,
        bottomMargin=40
    )

    styles = getSampleStyleSheet()

    story = []

    # Title
    story.append(
        Paragraph(
            title,
            styles["Title"]
        )
    )

    story.append(Spacer(1, 15))

    # Dataset summary
    story.append(
        Paragraph(
            f"<b>Dataset:</b> {df.shape[0]} rows × {df.shape[1]} columns",
            styles["Normal"]
        )
    )

    story.append(Spacer(1, 10))

    story.append(
        Paragraph(
            f"<b>Missing Values:</b> {int(df.isnull().sum().sum())}",
            styles["Normal"]
        )
    )

    story.append(Spacer(1, 10))

    story.append(
        Paragraph(
            f"<b>Duplicate Rows:</b> {int(df.duplicated().sum())}",
            styles["Normal"]
        )
    )

    story.append(Spacer(1, 20))

    # AI analysis
    story.append(
        Paragraph(
            "<b>AI-Generated Business Analysis</b>",
            styles["Heading2"]
        )
    )

    story.append(Spacer(1, 10))

    # Convert AI text into PDF paragraphs
    for line in analysis_text.split("\n"):

        line = line.strip()

        if line:

            safe_line = (
                line
                .replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
            )

            story.append(
                Paragraph(
                    safe_line,
                    styles["Normal"]
                )
            )

            story.append(Spacer(1, 6))

    doc.build(story)

    buffer.seek(0)

    return buffer
# ==========================================
# DASHBOARD GENERATOR
# ==========================================

def build_dashboard(df, file_name):
    """Create an interactive KPI dashboard for a structured uploaded dataset."""
    import plotly.express as px

    numeric_cols = df.select_dtypes(include="number").columns.tolist()
    categorical_cols = df.select_dtypes(
        include=["object", "category"]
    ).columns.tolist()

    st.markdown(f"## 🎯 Dashboard — {file_name}")
    st.caption("Interactive KPI and business overview generated from the uploaded dataset.")

    # KPI calculations
    total_rows = len(df)
    total_columns = len(df.columns)
    total_missing = int(df.isnull().sum().sum())
    duplicate_rows = int(df.duplicated().sum())

    # Useful business-like numeric metrics
    primary_numeric = numeric_cols[0] if numeric_cols else None
    secondary_numeric = numeric_cols[1] if len(numeric_cols) > 1 else None

    k1, k2, k3, k4 = st.columns(4)

    with k1:
        st.metric("Total Records", f"{total_rows:,}")

    with k2:
        st.metric("Total Columns", f"{total_columns:,}")

    with k3:
        st.metric("Missing Values", f"{total_missing:,}")

    with k4:
        st.metric("Duplicate Rows", f"{duplicate_rows:,}")

    if primary_numeric:
        a, b, c, d = st.columns(4)

        with a:
            st.metric(
                f"Total {primary_numeric}",
                f"{df[primary_numeric].sum(skipna=True):,.2f}"
            )

        with b:
            st.metric(
                f"Average {primary_numeric}",
                f"{df[primary_numeric].mean(skipna=True):,.2f}"
            )

        with c:
            st.metric(
                f"Maximum {primary_numeric}",
                f"{df[primary_numeric].max(skipna=True):,.2f}"
            )

        with d:
            st.metric(
                f"Minimum {primary_numeric}",
                f"{df[primary_numeric].min(skipna=True):,.2f}"
            )

    # Main dashboard charts
    dash_col1, dash_col2 = st.columns(2)

    with dash_col1:
        if categorical_cols:
            category = next(
                (
                    c for c in categorical_cols
                    if 2 <= df[c].nunique(dropna=True) <= 20
                ),
                None
            )

            if category:
                counts = (
                    df[category]
                    .dropna()
                    .value_counts()
                    .head(10)
                    .reset_index()
                )
                counts.columns = [category, "Count"]

                fig = px.bar(
                    counts,
                    x=category,
                    y="Count",
                    title=f"Top {category} Categories",
                    text="Count"
                )
                fig.update_layout(height=400)
                st.plotly_chart(fig, use_container_width=True)
            else:
                st.info("No suitable categorical column for the dashboard.")

    with dash_col2:
        if len(numeric_cols) >= 1:
            value_col = primary_numeric
            fig = px.histogram(
                df,
                x=value_col,
                nbins=20,
                title=f"Distribution — {value_col}"
            )
            fig.update_layout(height=400)
            st.plotly_chart(fig, use_container_width=True)

    # Second row
    dash_col3, dash_col4 = st.columns(2)

    with dash_col3:
        if len(numeric_cols) >= 2:
            fig = px.scatter(
                df,
                x=numeric_cols[0],
                y=numeric_cols[1],
                title=f"{numeric_cols[0]} vs {numeric_cols[1]}"
            )
            fig.update_layout(height=400)
            st.plotly_chart(fig, use_container_width=True)
        elif date_columns_for_dashboard(df):
            date_col = date_columns_for_dashboard(df)[0]
            dates = pd.to_datetime(df[date_col], errors="coerce").dropna()
            monthly = (
                dates.dt.to_period("M")
                .value_counts()
                .sort_index()
            )
            trend_df = pd.DataFrame({
                "Month": monthly.index.astype(str),
                "Records": monthly.values
            })
            fig = px.line(
                trend_df,
                x="Month",
                y="Records",
                markers=True,
                title=f"Records Over Time — {date_col}"
            )
            fig.update_layout(height=400)
            st.plotly_chart(fig, use_container_width=True)

    with dash_col4:
        if len(numeric_cols) >= 2:
            corr = df[numeric_cols].corr()
            fig = px.imshow(
                corr,
                text_auto=".2f",
                aspect="auto",
                title="Numeric Correlation Heatmap"
            )
            fig.update_layout(height=400)
            st.plotly_chart(fig, use_container_width=True)
        elif categorical_cols:
            category = next(
                (
                    c for c in categorical_cols
                    if 2 <= df[c].nunique(dropna=True) <= 8
                ),
                None
            )
            if category:
                pie_data = (
                    df[category]
                    .dropna()
                    .value_counts()
                    .head(8)
                    .reset_index()
                )
                pie_data.columns = [category, "Count"]
                fig = px.pie(
                    pie_data,
                    names=category,
                    values="Count",
                    hole=0.42,
                    title=f"{category} Share"
                )
                fig.update_layout(height=400)
                st.plotly_chart(fig, use_container_width=True)

    # Data quality panel
    st.markdown("### 🔎 Dashboard Data Quality")

    quality_df = pd.DataFrame({
        "Metric": [
            "Rows",
            "Columns",
            "Missing Values",
            "Duplicate Rows",
            "Numeric Columns",
            "Categorical Columns"
        ],
        "Value": [
            total_rows,
            total_columns,
            total_missing,
            duplicate_rows,
            len(numeric_cols),
            len(categorical_cols)
        ]
    })

    st.dataframe(
        quality_df,
        hide_index=True,
        use_container_width=True
    )


def date_columns_for_dashboard(df):
    detected = []

    for column in df.columns:
        if pd.api.types.is_datetime64_any_dtype(df[column]):
            detected.append(column)
            continue

        if df[column].dtype == "object":
            converted = pd.to_datetime(
                df[column],
                errors="coerce"
            )
            if converted.notna().mean() >= 0.7:
                detected.append(column)

    return detected


