theme_links = []
for key, label in THEME_OPTIONS.items():
    active = " active" if key == selected_theme else ""
    theme_links.append(
        f'<a class="{active.strip()}" href="?theme={key}">{label}</a>'
    )
theme_menu_html = "".join(theme_links)

